            "recognition" to AgentEntity("recognition",fields=listOf("id","groupId","provider","model","inputJson","inputFingerprint","state","resultJson","error","acceptedTitle","requestedAt","completedAt","workId","approvalId"),brief=listOf("id","groupId","provider","model","state","acceptedTitle","error","requestedAt","completedAt"),order="requestedAt DESC,id"),
