            "market_imports" to AgentEntity("market_imports",fields=listOf("id","fileHash","filename","format","observedAt","total","added","duplicates","versions","warningsJson","databaseVersion"),brief=listOf("id","filename","format","observedAt","total","added","duplicates","versions")),
            "price_history" to AgentEntity("price_decisions",fields=listOf("id","groupId","itemId","title","titleKey","edition","releaseYear","barcode","recordType","priceCents","currency","method","evidenceJson","provenanceJson","createdAt"),brief=listOf("id","groupId","itemId","title","recordType","priceCents","currency","method","createdAt"),order="createdAt DESC,id"),
