            "shopify_items" to AgentEntity("shopify_job_items",fields=listOf("id","jobId","groupId","itemId","expectedRevision","inputFingerprint","snapshotJson","creationKey","state","step","remoteJson","error","attempts","createdAt","updatedAt"),brief=listOf("id","jobId","groupId","itemId","state","step","remoteJson","error","attempts","updatedAt")),
            "shopify_reviews" to AgentEntity("shopify_reviews",fields=listOf("id","kind","payloadJson","bindingHash","state","resultJson","createdAt","completedAt"),brief=listOf("id","kind","state","resultJson","createdAt","completedAt")),
            "inventory_audit" to AgentEntity("inventory_audit",fields=listOf("id","groupId","action","beforeJson","afterJson","occurredAt"),brief=listOf("id","groupId","action","occurredAt")),
            "events" to AgentEntity("events",fields=listOf("id","sessionId","groupId","action","createdAt"),brief=listOf("id","sessionId","groupId","action","createdAt")),
            "transfers" to AgentEntity("transfer_jobs",fields=listOf("id","kind","state","completed","total","filename","sha256","error","createdAt","updatedAt"),brief=listOf("id","kind","state","completed","total","error","updatedAt")),
            "archives" to AgentEntity("archives",fields=listOf("id","sessionId","part","filename","groupIds","targetBytes","manifestJson","state","bytes","sha256","error"),brief=listOf("id","sessionId","part","filename","state","bytes","sha256","error")),
            "listing_plans" to AgentEntity("listing_plans",fields=listOf("id","groupId","itemId","inventoryRevision","inputFingerprint","payloadJson","errorsJson","state","createdAt"),brief=listOf("id","groupId","itemId","inventoryRevision","errorsJson","state","createdAt")),
            "agent_traces" to AgentEntity("agent_traces",fields=listOf("id","conversationId","tool","argumentsJson","state","summary","resultChars","durationMs","createdAt"),brief=listOf("id","tool","state","summary","resultChars","durationMs","createdAt"))
        )
        val special=mapOf(
            "inventory.search" to "query? string; session_id? UUID or latest; filter? ALL|UNPRICED|NEEDS_REVIEW|READY|MISSING_TITLE|MISSING_LOCATION|MISSING_BARCODE; condition?, location?, tags?, product_type?, shopify_state? string; has_photos? boolean; min_cents?, max_cents? integer CAD asking base; archived? boolean; offset? integer; limit?1..50",
            "inventory.get" to "group_id UUID. Compact full identity and validation; use record.field for long fields.",
            "inventory.stats" to "session_id? UUID or latest. Exact local counts and asking-price CAD totals; not sales/revenue.",
            "inventory.duplicates" to "by TITLE|BARCODE; session_id? UUID or latest; offset?; limit?1..20. Candidates only; copies are distinct.",
            "inventory.rank_market" to "currency CAD|USD; statistic MEDIAN|AVERAGE|HIGHEST; session_id? UUID or latest; limit?1..20. Computes compatible cohorts for the entire scope locally; no guessed FX.",
            "batch.review" to "session_id UUID or latest; offset?; limit?1..50. Actual item validation problems/photo counts.",
            "market.search" to "query string; currency?; edition?; year?; min_cents?; max_cents?; from? YYYY-MM-DD; until?; sort? RELEVANCE|PRICE_LOW|PRICE_HIGH|NEWEST|SAMPLES; history? boolean; offset?; limit?1..50",
            "market.recommend" to "group_id UUID; currency CAD|USD. Conservative actual sold cohort and statistics.",
            "photos.inspect" to "photo_id UUID. Local dimensions, orientation, capture metadata and verified integrity. No pixels/bytes are transmitted.",
            "record.field" to "entity (from schema); id canonical UUID; field allowlisted field; offset? character offset; length?1..4000. Read complete long fields in chunks; never protected credentials.",
            "tasks.status" to "task_id UUID. Actual owning recognition/Shopify state; queued is not completed.",
            "diagnostics.failures" to "period? today|yesterday|all; module? recognition|shopify|transfer|capture|agent|all; offset?; limit?1..50. Device-local dates.",
            "settings.public" to "No arguments. Explicit non-secret settings allowlist; credentials excluded.",
            "database.health" to "No arguments. Local quick/foreign-key checks, table counts and storage information; no network.",
            "shopify.catalog" to "query string; status empty|DRAFT|ACTIVE|ARCHIVED; cursor string. Explicit on-demand broker read; no upload/write.",
            "shopify.product" to "product_id typed Shopify Product GID; location_id Location GID. Explicit broker read, no write.",
            "shopify.connection" to "No arguments. On-demand paired broker health; credentials never returned.",
            "capabilities" to "No arguments. Static truthful permission/capability description; not an inspection."
        )
        val resources:List<String> get()=special.keys.toList()+entities.keys.map {"$it.list"}
        fun schema(resource:String):JSONObject {
            if(resource=="all") return JSONObject().put("resources",JSONArray(resources)).put("writes",JSONArray(AgentApplicationActions.actions)).put("discovery","Request a specific resource/action schema before calling it.")
            special[resource]?.let {return JSONObject().put("resource",resource).put("arguments",it)}
            val spec=entities[resource.removeSuffix(".list")] ?: error("Unknown resource. Request app_schema(all).")
            return JSONObject().put("resource",resource).put("arguments","id?, group_id?, session_id?, job_id?, conversation_id?, import_id?, item_id? (immutable SKU string), state?, query?, from?, until?, fields? array1..12 of allowlisted columns, offset?, limit?1..50. Only fields that exist on this entity may be used.")
                .put("fields",JSONArray(spec.fields)).put("defaultFields",JSONArray(spec.brief)).put("details","record.field reads any allowlisted field by UUID in bounded chunks.")
        }
    }
    private val cache=linkedMapOf<String,Pair<Long,JSONObject>>()
    private fun query(sql:String,args:List<Any?> = emptyList()):List<JSONObject> = repo.journal.openHelper.writableDatabase.query(sql,args.toTypedArray()).use {c->buildList {while(c.moveToNext()) add(cursorObject(c))}}
    private fun count(table:String,where:String="1",args:List<Any?> = emptyList()):Long=query("SELECT COUNT(*) n FROM $table WHERE ($where) AND ${trashVisibility(table)}",args).single().getLong("n")
    private fun keys(p:JSONObject,allowed:Set<String>,required:Set<String> = emptySet()) {require(p.keys().asSequence().all {it in allowed} && required.all {p.has(it)}) {"Unexpected or missing query arguments. Read app_schema for this resource."}}
    private fun text(p:JSONObject,key:String,default:String="",max:Int=300):String=if(p.has(key)) p.getString(key).also {require(it.length<=max && !it.contains('\u0000'))} else default
    private fun offset(p:JSONObject)=p.optInt("offset",0).also {require(it in 0..10_000_000)}
    private fun limit(p:JSONObject,max:Int=50)=p.optInt("limit",minOf(20,max)).also {require(it in 1..max)}
    private fun session(value:String):String=if(value=="latest") query("SELECT id FROM sessions WHERE id NOT IN (SELECT targetId FROM trash_entries WHERE kind='BATCH') ORDER BY createdAt DESC,id LIMIT 1").firstOrNull()?.getString("id") ?: error("No capture batches exist.") else requireUuid(value)
    private fun page(rows:List<JSONObject>,off:Int,lim:Int,total:Long?=null):JSONObject {val more=if(total==null) rows.size>lim else off+minOf(rows.size,lim)<total
        return JSONObject().put("items",JSONArray(rows.take(lim))).put("offset",off).put("returned",minOf(rows.size,lim)).put("nextOffset",if(more) off+minOf(rows.size,lim) else JSONObject.NULL).apply {if(total!=null) put("total",total)}}
    private fun inventoryWhere(p:JSONObject):Pair<String,List<Any?>> {
        val clauses=mutableListOf("i.groupId NOT IN (SELECT targetId FROM trash_entries WHERE kind='INVENTORY')","i.archived=?");val args=mutableListOf<Any?>(if(p.optBoolean("archived",false)) 1 else 0)
        val q=text(p,"query",max=200);if(q.isNotBlank()) {clauses+="(i.title LIKE ? ESCAPE '\\' OR i.itemId LIKE ? ESCAPE '\\' OR i.barcode LIKE ? ESCAPE '\\' OR i.tags LIKE ? ESCAPE '\\' OR i.description LIKE ? ESCAPE '\\' OR i.location LIKE ? ESCAPE '\\')";val v="%"+q.replace("\\","\\\\").replace("%","\\%").replace("_","\\_")+"%";repeat(6) {args+=v}}
        if(p.has("session_id")) {clauses+="g.sessionId=?";args+=session(p.getString("session_id"))}
        when(text(p,"filter","ALL")) {"ALL"->Unit;"UNPRICED"->clauses+="(i.priceCents IS NULL OR i.priceCents=0)";"NEEDS_REVIEW"->clauses+="i.ready=0";"READY"->clauses+="i.ready=1";"MISSING_TITLE"->clauses+="TRIM(i.title)=''";"MISSING_LOCATION"->clauses+="TRIM(i.location)=''";"MISSING_BARCODE"->clauses+="TRIM(i.barcode)=''";else->error("Unsupported inventory filter")}
        for((param,column) in listOf("condition" to "condition","location" to "location","product_type" to "productType","shopify_state" to "shopifyState")) if(p.has(param)) {clauses+="i.$column=?";args+=text(p,param,max=1000)}
        if(p.has("tags")) {clauses+="i.tags LIKE ? ESCAPE '\\'";args+="%"+text(p,"tags").replace("\\","\\\\").replace("%","\\%").replace("_","\\_")+"%"}
        if(p.has("has_photos")) clauses+=(if(p.getBoolean("has_photos")) "EXISTS" else "NOT EXISTS")+"(SELECT 1 FROM photos p WHERE p.groupId=i.groupId AND p.deleted=0 AND p.state='READY')"
        for(key in listOf("min_cents","max_cents")) if(p.has(key)) {val n=p.getLong(key);require(n in 0..InventoryRules.maxPriceCents);clauses+="i.priceCents ${if(key=="min_cents") ">=" else "<="} ?";args+=n}
        return clauses.joinToString(" AND ") to args
    }
    suspend fun overview():JSONObject=repo.mutate {
        val result=JSONObject();for((name,table) in listOf("inventory" to "inventory","batches" to "sessions","photos" to "photos","soldObservations" to "market_sales","tasks" to "agent_tasks","shopifyJobs" to "shopify_jobs")) result.put(name,count(table))
        result.put("unpriced",count("inventory","archived=0 AND (priceCents IS NULL OR priceCents=0)"));result.put("needsReview",count("inventory","archived=0 AND ready=0"))
        result.put("recognitionQueue",JSONArray(query("SELECT state,COUNT(*) count FROM recognition GROUP BY state"))).put("shopifyQueue",JSONArray(query("SELECT state,COUNT(*) count FROM shopify_jobs GROUP BY state")))
            .put("latestBatch",query("SELECT id,name,createdAt,finished FROM sessions WHERE id NOT IN (SELECT targetId FROM trash_entries WHERE kind='BATCH') ORDER BY createdAt DESC,id LIMIT 1").firstOrNull() ?: JSONObject.NULL)
            .put("note","Current local state only. Queued work is not proof of remote success. No provider or broker was contacted.")
    }
    suspend fun read(chat:ChatConversationRow,resource:String,p:JSONObject):JSONObject=withContext(Dispatchers.IO) {
        when(resource) {
            "capabilities"->{keys(p,emptySet());JSONObject().put("permission",AgentPermission.of(chat).label).put("resources",JSONArray(resources)).put("modifications",AgentPermission.of(chat)==AgentPermission.FULL_AGENT).put("photos","Metadata only; a human must explicitly attach a derivative and press Send.").put("monitoring",false).put("inspectedRecords",0)}
            "inventory.search","batch.review"->{keys(p,setOf("query","session_id","filter","archived","offset","limit","condition","location","tags","product_type","shopify_state","has_photos","min_cents","max_cents"),if(resource=="batch.review") setOf("session_id") else emptySet());val (where,args)=inventoryWhere(p);val off=offset(p);val lim=limit(p)
                val fields=entities.getValue("inventory").brief.joinToString(",") {"i.$it"};val rows=query("SELECT $fields,g.sessionId,(SELECT COUNT(*) FROM photos p WHERE p.groupId=i.groupId AND p.deleted=0) photoCount FROM inventory i JOIN groups g ON g.id=i.groupId WHERE $where ORDER BY i.createdAt DESC,i.itemId LIMIT ? OFFSET ?",args+listOf(lim+1,off))
                if(resource=="batch.review") rows.forEach {r->val item=repo.journal.inventoryDao().item(r.getString("groupId"))!!;r.put("problems",JSONArray(inventoryProblems(item,repo.dao.photos(item.groupId),repo)))}
                val total=query("SELECT COUNT(*) n FROM inventory i JOIN groups g ON g.id=i.groupId WHERE $where",args).single().getLong("n");page(rows,off,lim,total)}
            "inventory.get"->{check(repo.journal.trashDao().target("INVENTORY",p.optString("group_id"))==null) {"Record is in local Trash."};keys(p,setOf("group_id"),setOf("group_id"));val id=requireUuid(p.getString("group_id"));val item=repo.journal.inventoryDao().item(id) ?: error("Item missing");inventoryJson(item).put("problems",JSONArray(inventoryProblems(item,repo.dao.photos(id),repo))).put("sessionId",repo.dao.group(id).sessionId).put("photoCount",repo.dao.photos(id).count {!it.deleted})}
            "inventory.stats"->{keys(p,setOf("session_id"));val (where,args)=inventoryWhere(p);query("SELECT COUNT(*) copies,SUM(CASE WHEN i.priceCents IS NULL OR i.priceCents=0 THEN 1 ELSE 0 END) unpriced,SUM(i.ready) ready,COALESCE(SUM(i.priceCents),0) askingBaseCentsCad FROM inventory i JOIN groups g ON g.id=i.groupId WHERE $where",args).single().put("amountMeaning","Local CAD asking base prices, not realized sales or market value.")}
            "inventory.duplicates"->{keys(p,setOf("by","session_id","offset","limit"),setOf("by"));val by=p.getString("by");require(by in listOf("TITLE","BARCODE"));val (where,args)=inventoryWhere(p)
                val groups=linkedMapOf<String,MutableList<JSONObject>>();query("SELECT i.groupId,i.itemId,i.title,i.barcode,i.condition,i.location,i.batchId,i.releaseYear,i.edition FROM inventory i JOIN groups g ON g.id=i.groupId WHERE $where ORDER BY i.itemId",args).forEach {r->val key=if(by=="TITLE") InventoryRules.normalizedTitle(r.getString("title")) else r.getString("barcode");if(key.isNotBlank()) groups.getOrPut(key) {mutableListOf()}.add(r)}
                val duplicates=groups.filterValues {it.size>1}.map {(key,rows)->JSONObject().put("match",key).put("copies",rows.size).put("examples",JSONArray(rows.take(10))).put("note","Potential duplicate titles/barcodes; physical copies remain separate. Query the title/Item IDs for all details.")};page(duplicates.drop(offset(p)),offset(p),limit(p,20),duplicates.size.toLong())}
            "inventory.rank_market"->ranking(p)
            "market.search"->{keys(p,setOf("query","currency","edition","year","min_cents","max_cents","from","until","sort","history","offset","limit"),setOf("query"));val currency=text(p,"currency");require(currency.isBlank() || currency in listOf("CAD","USD"));val sort=text(p,"sort","RELEVANCE");require(sort in listOf("RELEVANCE","PRICE_LOW","PRICE_HIGH","NEWEST","SAMPLES"));for(k in listOf("from","until")) if(p.has(k)) LocalDate.parse(p.getString(k))
                val off=offset(p);val lim=limit(p);val page=repo.searchMarket(MarketFilters(text(p,"query"),currency,text(p,"edition"),if(p.has("year")) p.getInt("year") else null,if(p.has("min_cents")) p.getLong("min_cents") else null,if(p.has("max_cents")) p.getLong("max_cents") else null,text(p,"from"),text(p,"until"),sort,p.optBoolean("history")),off,lim)
                JSONObject().put("items",JSONArray(page.groups.map {r->JSONObject().put("titleKey",r.titleKey).put("title",r.title).put("currency",r.currency).put("count",r.samples).put("lowestCents",r.low).put("highestCents",r.high).put("newestSale",r.newest).put("edition",r.edition).put("year",r.year ?: JSONObject.NULL)})).put("offset",off).put("returned",page.groups.size).put("nextOffset",if(page.groups.size==lim) off+lim else JSONObject.NULL).put("approximate",page.approximate).put("correctedQuery",page.correctedQuery).put("note","Browsing groups; approximate matches are not approved pricing evidence.")}
            "market.recommend"->{keys(p,setOf("group_id","currency"),setOf("group_id","currency"));val c=p.getString("currency");require(c in listOf("CAD","USD"));val r=repo.recommendMarket(requireUuid(p.getString("group_id")),c);if(r==null) JSONObject().put("compatibleSoldCount",0).put("message","No compatible evidence. No price invented.") else marketRecommendationJson(r).apply {remove("ids");put("evidenceIdsPreview",JSONArray(r.ids.take(10)));put("evidenceCount",r.ids.size)}}
            "photos.inspect"->{keys(p,setOf("photo_id"),setOf("photo_id"));val photo=repo.dao.photo(requireUuid(p.getString("photo_id")));check(photo.state=="READY" && !photo.deleted);val file=repo.original(photo.id);val bounds=android.graphics.BitmapFactory.Options().apply {inJustDecodeBounds=true};android.graphics.BitmapFactory.decodeFile(file.path,bounds);val exif=androidx.exifinterface.media.ExifInterface(file)
                JSONObject().put("id",photo.id).put("groupId",photo.groupId).put("role",photo.role).put("capturedAt",photo.capturedAt).put("bytes",file.length()).put("width",bounds.outWidth).put("height",bounds.outHeight).put("orientation",exif.getAttributeInt(androidx.exifinterface.media.ExifInterface.TAG_ORIENTATION,1)).put("integrityVerified",hashFile(file)==photo.sha256).put("pixelsTransmitted",false)}
            "record.field"->{keys(p,setOf("entity","id","field","offset","length"),setOf("entity","id","field"));val e=entities[p.getString("entity")] ?: error("Unknown entity");val f=p.getString("field");require(f in e.fields);val row=query("SELECT $f FROM ${e.table} WHERE ${e.key}=? AND ${trashVisibility(e.table)}",listOf(requireUuid(p.getString("id")))).singleOrNull() ?: error("Record missing");var value=row.get(f);if(value is String) {value=try {safeAgentJson(JSONTokener(value).nextValue()).toString()} catch(_:Exception) {safeAgentText(value)}}
                val off=offset(p);val length=p.optInt("length",3000).also {require(it in 1..4000)};val str=value.toString();require(off<=str.length);JSONObject().put("entity",p.getString("entity")).put("id",p.getString("id")).put("field",f).put("text",str.drop(off).take(length)).put("totalCharacters",str.length).put("nextOffset",if(off+length<str.length) off+length else JSONObject.NULL)}
            "tasks.status"->{keys(p,setOf("task_id"),setOf("task_id"));val t=repo.journal.agentTaskDao().get(requireUuid(p.getString("task_id"))) ?: error("Task missing");val s=repo.agentTaskStatus(t);JSONObject().put("id",t.id).put("kind",t.kind).put("state",s.state).put("done",s.done).put("total",s.total).put("detail",s.detail).put("jobs",s.jobs).put("result",JSONObject(t.resultJson))}
            "settings.public"->{keys(p,emptySet());AgentApplicationActions.publicSettings(repo)}
            "database.health"->{keys(p,emptySet());val check=query("PRAGMA quick_check(1)").firstOrNull();val foreign=query("PRAGMA foreign_key_check");overview().put("quickCheck",check).put("foreignKeyViolations",foreign.size).put("freeBytes",repo.originals.usableSpace).put("originalBytes",repo.originals.listFiles()?.filter {it.isFile}?.sumOf {it.length()} ?: 0).put("credentialsInspected",false).put("tables",JSONArray((snapshotTables+"market_sales").map {JSONObject().put("table",it).put("rows",count(it))})).put("pageCount",query("PRAGMA page_count").single()).put("pageSize",query("PRAGMA page_size").single()).put("freePages",query("PRAGMA freelist_count").single())}
            "diagnostics.failures"->failures(p)
            "shopify.catalog","shopify.product","shopify.connection"->{check(repo.preferences.getBoolean("shopifyPaired",false)) {"Shopify is not paired. Local job/status data is still available."};val gateway=ShopifyBrokerClient(repo.context,repo.preferences.getString("shopifyBroker","").orEmpty())
                when(resource) {"shopify.catalog"->{keys(p,setOf("query","status","cursor"),setOf("query","status","cursor"));gateway.call(newId(),"browse",JSONObject().put("query",text(p,"query",max=200)).put("status",text(p,"status")).put("cursor",text(p,"cursor",max=2000))).also {page->val nodes=page.getJSONArray("nodes");val kept=JSONArray();for(i in 0 until nodes.length()) {val node=nodes.getJSONObject(i);if(repo.journal.trashDao().target("PRODUCT",stableRowId(node.getString("id")))==null) kept.put(node)};page.put("nodes",kept)}}
                    "shopify.product"->{keys(p,setOf("product_id","location_id"),setOf("product_id","location_id"));check(repo.journal.trashDao().target("PRODUCT",stableRowId(text(p,"product_id")))==null) {"This listing was removed from SnapIMS."};gateway.call(newId(),"product",JSONObject().put("productId",text(p,"product_id")).put("locationId",text(p,"location_id")))}
