                if(item.title.isNotBlank()) try {val cohortKey=listOf(item.title,item.edition,item.releaseYear,item.barcode).joinToString("\u0000");val r=if(cohorts.containsKey(cohortKey)) cohorts[cohortKey] else repo.recommendMarketLocked(item,currency).also {cohorts[cohortKey]=it}
                    if(r!=null) values+=JSONObject().put("groupId",item.groupId).put("itemId",item.itemId).put("title",item.title).put("currency",currency).put("soldCount",r.stats.count).put("statistic",stat).put("cents",when(stat) {"MEDIAN"->r.stats.medianCents;"AVERAGE"->r.stats.averageCents;else->r.stats.highestCents}).put("newestSale",r.newest)
