        if(module in listOf("all","transfer")) parts+="SELECT id,'' groupId,'transfer' module,state,error,CAST(strftime('%s',updatedAt) AS INTEGER)*1000 time FROM transfer_jobs WHERE state IN ('ERROR','INTERRUPTED')"
        if(module in listOf("all","agent")) parts+="SELECT id,'' groupId,'agent' module,state,summary error,createdAt+durationMs time FROM agent_traces WHERE state IN ('ERROR','INTERRUPTED')"
        if(module in listOf("all","shopify")) parts+="SELECT id,'' groupId,'shopify' module,state,error,updatedAt time FROM shopify_jobs WHERE error!=''"
        if(module in listOf("all","capture")) {parts+="SELECT id,groupId,'capture' module,state,error,NULL time FROM photos WHERE error!=''";parts+="SELECT id,'' groupId,'capture' module,state,error,NULL time FROM archives WHERE state='ERROR'"}
        if(module in listOf("all","agent")) parts+="SELECT id,'' groupId,'agent' module,state,error,updatedAt time FROM agent_tasks WHERE error!=''"
