        return page(query("SELECT * FROM $base WHERE $where ORDER BY time DESC,id LIMIT ? OFFSET ?",args+listOf(lim+1,off)),off,lim,count(base,where,args)).put("undatedFailures",count(base,"time IS NULL")).put("historyLimit","Only retained failures are available. Capture/archive errors have no recorded failure timestamp: they appear in period=all, and undatedFailures may also belong to the selected day. Successful retries may replace some native error state; no missing event time is invented.").put("timezone",zone.id).put("period",period)
